import{_ as r,o as l,c as t,a5 as e}from"./chunks/framework.CnBNXlt7.js";const m=JSON.parse('{"title":"境外银行卡办理指南","description":"","frontmatter":{},"headers":[],"relativePath":"trip/overseas-bank-card.md","filePath":"trip/overseas-bank-card.md","lastUpdated":1745479886000}'),s={name:"trip/overseas-bank-card.md"};function i(o,a,n,c,d,h){return l(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="境外银行卡办理指南" tabindex="-1">境外银行卡办理指南 <a class="header-anchor" href="#境外银行卡办理指南" aria-label="Permalink to &quot;境外银行卡办理指南&quot;">​</a></h1><p>境内卡参考<a href="./../daily/card">这篇</a></p><h2 id="储蓄卡-借记卡" tabindex="-1">储蓄卡/借记卡 <a class="header-anchor" href="#储蓄卡-借记卡" aria-label="Permalink to &quot;储蓄卡/借记卡&quot;">​</a></h2><h3 id="汇丰-hk" tabindex="-1">汇丰 HK <a class="header-anchor" href="#汇丰-hk" aria-label="Permalink to &quot;汇丰 HK&quot;">​</a></h3><p><strong>汇丰 ONE</strong><br> 去当地开户即可，需要排队很久，不过只要能取到号就可以，一定会给你办下来的(无论是否下班，银行下班17:00，因为取到号，在里面等着即可，18:30办理完成，直接开卡)。但是要等很久，我等了2个半小时，手续比较多。需要带<strong>身份证+通行证+入关凭条</strong>。(时效性2024年)</p><details class="details custom-block"><summary>笔者详细流程</summary><p>笔者是临时起意，16:00左右在旺角分行取了号，银行17:00下班直接关门，不再接收新人，但已经取号的人会全部办理完毕。<br> 笔者运气比较好，接待笔者的都是很客气的。<br> 前后有三个人接待。首先是接待台，年轻小伙 A 普通话不是很标准，我说没关系的，可以听懂的。但是 A 还是出于礼貌，换了应该相对好一点的小伙 B。就闲聊开户的用途，及 APP 下载，手机注册等等事宜。<br> 后面慢慢等号，因为知道时间很久，就在外面闲逛。<br> 等的差不多了，小伙 C 接待，去专属柜台，跟小包厢一样，询问开户用途，<strong>通行证+入关凭条</strong>，中间聊的非常多。最好说明自己的财力雄厚，擅于投资。<br> 沟通完就很快制卡，直接领到卡片，里面有很多柜台机子，看好机子的用途再操作</p></details><p>其他账户，需要理财资产大于50万港币或者等值外币</p><p>开好<strong>汇丰 ONE</strong> 账户之后，可以在线申请<strong>万事达借记卡</strong></p><details class="details custom-block"><summary>修改个人信息</summary><p>如果您满足以下3个条件，可通过网上理财更改个人信息：</p><ul><li>已激活您的保安编码器或流动保安编码</li><li>可通过网上理财管理您的账户或信用卡</li><li>在银行登记了有效的手机号码和电邮地址</li></ul><p>通过网上理财只需几个步骤，就可随时更新您的个人资料，十分方便。请您准备好保安编码器或流动保安编码，然後按照以下步骤更改您的通讯地址：</p><ul><li>登录网上理财</li><li>在主页顶部选单选择“理财”</li><li>在“个人设置”下选择“更新个人资料”</li><li>在“更新您的住址、办事处及其他通讯地址”处选择“是”</li><li>填写网上的申请表格</li></ul><p>请留意：</p><ul><li>如需更改指定账户或信用卡的通讯地址，请在“第三步 - 设立新地址为您的户口通讯地址”下选择对应账户或信用卡。</li><li>如需更改非固定格式的地址，请选择“请点选，若您的地址在香港特区以外”。</li><li>如需更改您的保管箱、保险和强积金资料，请选择“保管箱/保险/强积金/其他”下的“是”</li></ul></details><h3 id="中国银行-hk" tabindex="-1">中国银行 HK <a class="header-anchor" href="#中国银行-hk" aria-label="Permalink to &quot;中国银行 HK&quot;">​</a></h3><details class="details custom-block"><summary>内地见证开户(仅留学)</summary><p>内地<a href="https://www.bochk.com/m/sc/crossborder/personal/financialservicehk/account.html" target="_blank" rel="noreferrer">见证开户</a>，但内地见证只能办<strong>留学见证</strong>。<a href="https://www.bochk.com/dam/more/BOC_list_SC.pdf" target="_blank" rel="noreferrer">内地见证网点</a>，提前给银行打电话询问是否可以见证，此表中大多数银行不支持见证的。</p></details><p>通关到达香港即可，接入 HK 的 WiFi 即可在线办理。</p><div class="warning custom-block"><p class="custom-block-title">需要准备 (注意时效性 2024年本人开户流程)</p><ol><li>首先得过境到达香港。</li><li>支付宝搜索“移民局”在线开具通关凭证，下载到手机</li><li>港澳通行证</li><li>下载“中银香港” APP (全称是<strong>BOCHK中银香港</strong>)</li><li>连接香港的 WiFi</li><li>打开 APP 即可在线开户</li></ol></div><p>需要实体卡可以在线申领，现在可以直接填写简体中文地址，寄到大陆。(注意：查不到邮件信息，发的是挂号信，需要去邮箱里自己取)</p><div class="danger custom-block"><p class="custom-block-title">2025年1月起 万事达扣账卡</p><p>普通用户也可在 APP 自助申请 <strong>万事达扣账卡</strong><br><strong>路径</strong>：登入-选单-账户-申请中银卡/扣账卡-中银万事达扣账卡<br> 先到先得，后续是否会优化掉，不知道。</p></div><h3 id="n26" tabindex="-1">N26 <a class="header-anchor" href="#n26" aria-label="Permalink to &quot;N26&quot;">​</a></h3><h2 id="信用卡" tabindex="-1">信用卡 <a class="header-anchor" href="#信用卡" aria-label="Permalink to &quot;信用卡&quot;">​</a></h2><h3 id="汇丰-hk-1" tabindex="-1">汇丰 HK <a class="header-anchor" href="#汇丰-hk-1" aria-label="Permalink to &quot;汇丰 HK&quot;">​</a></h3><p>在线申请即可，需要香港本地居民或者存款超过10万港币或者等值外币</p>',19)])])}const u=r(s,[["render",i]]);export{m as __pageData,u as default};
